+fn strong_etag(response: &reqwest::Response) -> Option<&HeaderValue> {
+    let etag = response.headers().get(ETAG)?;
+    let value = etag.as_bytes().strip_prefix(b"\"")?.strip_suffix(b"\"")?;
+    if !value
+        .iter()
